// Generated by vibelang from worker/runners/Overflow.ts; the migrate flow writes it again with each batch.
import * as WriteAuthority from "../WriteAuthority.js";
import { AgentRunner } from "@smthrs/agent";
import { Effect, Option, Schema } from "effect";
import { SqlClient } from "effect/sql";
import { MODEL_KINDS } from "../../src/features/personal-model/contract.js";
import * as PersonalStore from "../personal/Store.js";
import * as Store from "./Store.js";
// Overflow on Cloudflare (decision 0144, docs/features/agent-runners.md#overflow). A repository Admin turns it on with
// one of their own API-key connections; the host then mints the overflow runner's token, registers its SHA-256 as the
// runner `cloudflare-overflow`, and seals the token under SECRETS_KEY. When a job has waited past the setting's
// `minQueuedSeconds` and that runner isn't awake, the job store's probe wakes the repository's overflow box
// (worker/BranchSandboxes.ts), which runs plain `smthrs runner serve` from `boxPlan`. The box holds placeholders only:
// its egress puts the runner token in its requests to this deployment, and the Admin's key in its agent's requests to
// the key's host (worker/secrets/SandboxEgress.ts `forwardOverflow`). Nobody handles the token: no person sees it, and
// no log, journal or table holds it but sealed.
/** The overflow runner's name on every repository: one per repository. */
export const RUNNER = "cloudflare-overflow";
/** The label the overflow runner always carries, beside the setting's. */
export const LABEL = "cloudflare";
/** The cipher context of a repository's overflow token: a ciphertext moved to another repository doesn't open. */
export const tokenContext = (repoId, version) => ({ id: repoId, name: "overflow-runner", version });
/** How long a box's runner serves with no job before it ends and the box sleeps. */
export const IDLE_EXIT_SECONDS = 300;
/** How recently the overflow runner must have asked for the host to count its box awake. */
export const AWAKE_SECONDS = 45;
/** What an Admin sets. */
export const Setting = Schema.Struct({
    connectionId: Schema.String.check(Schema.isMinLength(1), Schema.isMaxLength(100)),
    profile: AgentRunner.Profile,
    argv: Schema.Array(Schema.String.check(Schema.isMinLength(1), Schema.isMaxLength(1000))).check(Schema.isMinLength(1), Schema.isMaxLength(32)),
    labels: Schema.Array(AgentRunner.Label).check(Schema.isMaxLength(16)),
    minQueuedSeconds: Schema.Int.check(Schema.isBetween({ minimum: 0, maximum: 86_400 })),
    capacity: Schema.Int.check(Schema.isBetween({ minimum: 1, maximum: 64 })),
});
/** The runner's labels: the setting's and `cloudflare`. */
export const labelsOf = (setting) => [
    ...new Set([...setting.labels, LABEL]),
];
/**
 * The Admin's connection the setting names, when it is theirs, active, and a key on a model wire (`MODEL_KINDS`): its
 * protocol and base URL, whose host the egress binds the key to.
 */
export const connectionOf = (personId, connectionId) => Effect.map(PersonalStore.saved(personId), (saved) => {
    const row = saved.find((each) => each.id === connectionId);
    return row !== undefined && row.active && MODEL_KINDS.includes(row.kind) && row.protocol !== null &&
        row.baseUrl !== null
        ? Option.some({ protocol: row.protocol, baseUrl: row.baseUrl })
        : Option.none();
});
/**
 * Locks the overflow runner's row, then the repository's overflow row: the order every release writes them in (the
 * runner's registration, then the setting), so a write here and one from the release before it, both live while a
 * deploy runs, never deadlock (decision 0148).
 */
const lockRunnerThenOverflow = (repoId) => Effect.flatMap(SqlClient.SqlClient, (sql) => Effect.andThen(sql `SELECT 1 FROM runners WHERE repo_id = ${repoId} AND name = ${RUNNER} FOR UPDATE`, sql `SELECT 1 FROM repo_overflow WHERE repo_id = ${repoId} FOR UPDATE`));
/**
 * Turns overflow on, or changes it, for `write.repoId`: registers the overflow runner by the minted token's SHA-256
 * (`Store.addRunner`, which refuses its old token from then on) and keeps the setting with the sealed token, in one
 * transaction under the step's invocation key.
 */
export const set = (write, by) => Store.refusedWhenLate(write.repoId, RUNNER, by, Effect.flatMap(SqlClient.SqlClient, (sql) => sql.withTransaction(Effect.gen(function* () {
    yield* WriteAuthority.bound;
    // A replay answers what its action did, before anything is written (decision 0148).
    const before = yield* Store.replayed("runners", write.repoId, RUNNER, by);
    if (before !== undefined)
        return before;
    yield* lockRunnerThenOverflow(write.repoId);
    const change = yield* Store.addRunner({
        repoId: write.repoId,
        name: RUNNER,
        tokenSha256: write.tokenSha256,
        labels: labelsOf(write),
        capacity: write.capacity,
        repoAuthorized: write.repoAuthorized,
    }, by);
    // Written again, or refused by its fence: the setting stays as it is.
    if (change !== "set")
        return change;
    yield* sql `
        INSERT INTO repo_overflow (repo_id, person_id, connection_id, origin, profile, argv, labels, min_queued_seconds,
          capacity, token_ciphertext, token_nonce, key_version, updated_by)
        VALUES (${write.repoId}, ${write.personId}, ${write.connectionId}, ${write.origin}, ${write.profile},
          ${JSON.stringify(write.argv)}::jsonb, ARRAY(SELECT jsonb_array_elements_text(${JSON.stringify(write.labels)}::jsonb)),
          ${write.minQueuedSeconds}, ${write.capacity}, ${write.token.ciphertext}, ${write.token.nonce},
          ${write.token.keyVersion}, ${by.actorId})
        ON CONFLICT (repo_id) DO UPDATE SET person_id = EXCLUDED.person_id, connection_id = EXCLUDED.connection_id,
          origin = EXCLUDED.origin, profile = EXCLUDED.profile, argv = EXCLUDED.argv, labels = EXCLUDED.labels,
          min_queued_seconds = EXCLUDED.min_queued_seconds, capacity = EXCLUDED.capacity,
          token_ciphertext = EXCLUDED.token_ciphertext, token_nonce = EXCLUDED.token_nonce,
          key_version = EXCLUDED.key_version, updated_by = EXCLUDED.updated_by, updated_at = now(), reconfirm_at = NULL`;
    // The setting's own write may have waited too: still within the authority's deadline, or none of it holds.
    yield* Store.commitWithin(by);
    return change;
}))));
/** Turns overflow off: the overflow runner's token is refused from now on, and the sealed token is gone. */
export const remove = (write, by) => Store.refusedWhenLate(write.repoId, RUNNER, by, Effect.flatMap(SqlClient.SqlClient, (sql) => sql.withTransaction(Effect.gen(function* () {
    yield* WriteAuthority.bound;
    const before = yield* Store.replayed("runners", write.repoId, RUNNER, by);
    if (before !== undefined)
        return before;
    yield* lockRunnerThenOverflow(write.repoId);
    const change = yield* Store.removeRunner({ repoId: write.repoId, name: RUNNER }, by);
    // Written again, or refused by its fence: the setting stays as it is.
    if (change !== "removed" && change !== "missing")
        return change;
    yield* sql `DELETE FROM repo_overflow WHERE repo_id = ${write.repoId}`;
    yield* Store.commitWithin(by);
    return change;
}))));
/** A repository's overflow, when it is on. */
export const read = (repoId) => Effect.flatMap(SqlClient.SqlClient, (sql) => Effect.map(sql `
        SELECT repo_id AS "repoId", person_id AS "personId", connection_id AS "connectionId", origin, profile, argv,
          labels, min_queued_seconds AS "minQueuedSeconds", capacity, token_ciphertext AS ciphertext,
          token_nonce AS nonce, key_version AS "keyVersion"
        FROM repo_overflow WHERE repo_id = ${repoId} AND reconfirm_at IS NULL`, ([row]) => row === undefined ? Option.none() : Option.some({
    repoId: row.repoId,
    personId: row.personId,
    connectionId: row.connectionId,
    origin: row.origin,
    profile: row.profile,
    argv: row.argv,
    labels: row.labels,
    minQueuedSeconds: row.minQueuedSeconds,
    capacity: row.capacity,
    token: { ciphertext: row.ciphertext, nonce: row.nonce, keyVersion: row.keyVersion },
})));
/**
 * Whether job `key` needs its repository's overflow box now: it is queued, pinned to no runner, claimable for at least
 * the repository's `minQueuedSeconds`, and the overflow runner hasn't asked in `AWAKE_SECONDS` (its box sleeps).
 */
export const due = (key) => Effect.flatMap(SqlClient.SqlClient, (sql) => Effect.map(sql `
        SELECT j.repo_id AS "repoId" FROM agent_jobs j JOIN repo_overflow o ON o.repo_id = j.repo_id AND o.reconfirm_at IS NULL
        WHERE j.key = ${key} AND j.status = 'queued' AND NOT j.cancel_requested AND j.pinned_runner IS NULL
          AND greatest(j.created_at, coalesce(j.not_before, j.created_at))
            <= now() - o.min_queued_seconds * interval '1 second'
          AND NOT EXISTS (
            SELECT 1 FROM runners r WHERE r.repo_id = j.repo_id AND r.name = ${RUNNER} AND r.removed_at IS NULL
              AND r.seen_at > now() - ${AWAKE_SECONDS}::int * interval '1 second')`, ([row]) => (row === undefined ? Option.none() : Option.some(row))));
/** The id of a repository's overflow box, as its `SandboxObject` and the sandbox ledger name it. */
export const boxId = (repoId) => `overflow-${repoId}`;
/** Whether `branchId` names an overflow box. */
export const isBox = (branchId) => branchId.startsWith("overflow-");
/**
 * The variables the box's runner and agent read the Admin's model from: its key (a placeholder), its base URL and its
 * wire (`PROTOCOLS`). Smithers names no vendor here: the setting's `argv` maps them to what its agent reads.
 */
export const MODEL_VARIABLES = {
    key: "SMITHERS_MODEL_KEY",
    baseUrl: "SMITHERS_MODEL_BASE_URL",
    protocol: "SMITHERS_MODEL_PROTOCOL",
};
/** Where the box's runner keeps its state and its mirror of the repository. */
export const BOX_HOME = "/home/smithers";
const quoted = (text) => `'${text.replace(/'/g, `'\\''`)}'`;
/**
 * The box's plan for `overflow`: its runner pulls from `overflow.origin` as `cloudflare-overflow` with the token's
 * placeholder, takes only jobs that waited `minQueuedSeconds`, ends after `IDLE_EXIT_SECONDS` with none, and runs the
 * setting's profile with the key's placeholder in its environment. The box is the runner's alone, so it admits up to
 * its CPUs and keeps 5 GB of its disk, not 40. `mirror` is the repository's read-only remote (the forge proxy).
 */
export const boxPlan = (overflow, placeholders, model, mirror) => {
    const state = `${BOX_HOME}/runner`;
    const config = {
        origin: overflow.origin,
        name: RUNNER,
        capacity: overflow.capacity,
        stateDir: state,
        minQueuedSeconds: overflow.minQueuedSeconds,
        idleExitSeconds: IDLE_EXIT_SECONDS,
        admission: { loadPerCpu: 1, diskFloorGb: 5 },
        repositories: { [overflow.repoId]: { mirror: `${BOX_HOME}/mirror` } },
        profiles: { [overflow.profile]: { argv: overflow.argv, secretEnv: [MODEL_VARIABLES.key] } },
    };
    return {
        environment: [
            `${MODEL_VARIABLES.key}=${placeholders.key}`,
            `${MODEL_VARIABLES.baseUrl}=${model.baseUrl}`,
            `${MODEL_VARIABLES.protocol}=${model.protocol}`,
            "",
        ].join("\n"),
        config: JSON.stringify(config),
        token: placeholders.token,
        script: [
            // An image built without the runner (infra/sandbox/pack-cli.mjs) can't serve: exit 3.
            "command -v smthrs >/dev/null && command -v jj >/dev/null || exit 3",
            "set -e",
            `mkdir -p ${state}`,
            // One start at a time, and none while the runner serves: it inherits the lock and holds it until it ends.
            `exec 9>${state}/serve.lock`,
            "flock -n 9 || exit 0",
            `[ -d ${BOX_HOME}/mirror/.jj ] || jj git clone ${quoted(mirror)} ${BOX_HOME}/mirror >${state}/clone.log 2>&1`,
            `setsid nohup smthrs runner serve --config ${state}/runner.json >>${state}/serve.log 2>&1 </dev/null &`,
            "exit 0",
        ].join("\n"),
    };
};
/**
 * The sandbox branch of `repoId`'s overflow box (`github/<owner>/<name>`): no git branch, since it checks nothing out,
 * and the `overflow` kind in the sandbox ledger (worker/branch/Budget.ts `kindOf`).
 */
export const boxBranch = (repoId) => {
    const [, owner = "", name = ""] = repoId.split("/");
    return { branchId: boxId(repoId), owner, name, branch: "", forge: "github" };
};
